import {garmentRadius,frontSurface,fittedSleeve} from './garment-fit.js';
import {applyGarmentSurface} from './garment-surface.js';
import * as T from './vendor/three.module.js';
import {releaseModel} from './studio-models.js';
export function createTailoring(body,legs,arms=[]){const extras=[];const root=new T.Group();root.name='tailored-body';root.userData.wardrobeSlot='garment';body.add(root);let key='',spec=null,mesh=null,rest=null,sleeping=false,rain=false;
 function set(v){const k=JSON.stringify(v);if(k===key)return;key=k;for(const c of [...root.children,...extras])releaseModel(c);extras.length=0;spec=v;mesh=null;if(!v)return;const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const c=canvas.getContext('2d');c.fillStyle=v.color;c.fillRect(0,0,256,256);c.fillStyle=v.accent;if(v.pattern==='check'){c.globalAlpha=.45;c.fillRect(0,0,128,256);c.fillRect(0,0,256,128)}if(v.pattern==='stripe'){c.fillRect(0,0,256,40);c.fillRect(0,128,256,40)}if(v.pattern==='dots')for(const [x,y]of [[64,64],[192,192]]){c.beginPath();c.arc(x,y,18,0,Math.PI*2);c.fill()}if(v.pattern==='flower')for(const [x,y]of [[64,64],[192,192]]){for(let i=0;i<5;i++){const a=i*Math.PI*2/5;c.beginPath();c.arc(x+Math.cos(a)*14,y+Math.sin(a)*14,10,0,Math.PI*2);c.fill()}}c.globalAlpha=1;const texture=new T.CanvasTexture(canvas);texture.colorSpace=T.SRGBColorSpace;texture.wrapS=texture.wrapT=T.RepeatWrapping;texture.repeat.set(2*Math.PI*.35/(v.patternScale*2),.5/(v.patternScale*2));const material=new T.MeshPhysicalMaterial({map:texture,roughness:.95,sheen:.6,side:T.DoubleSide});
 applyGarmentSurface(material,v);
 if(v.kind!=='skirt')for(const [index,arm] of arms.entries()){const sleeveMaterial=applyGarmentSurface(new T.MeshPhysicalMaterial({color:v.color,side:T.DoubleSide,roughness:.95,sheen:.6}),{...v,artwork:null});const sleeve=new T.Mesh(fittedSleeve(index?1:-1),sleeveMaterial);sleeve.name='tailored-sleeve';sleeve.userData.wardrobeSlot='garment';sleeve.castShadow=sleeve.receiveShadow=true;arm.add(sleeve);extras.push(sleeve);const cuff=new T.Mesh(new T.TorusGeometry(.106,.003,8,48),sleeveMaterial);cuff.rotation.x=Math.PI/2;cuff.scale.y=1.08;cuff.position.set((index?1:-1)*.035,-.234,0);sleeve.add(cuff);}
 if(v.kind==='set'){const pants=applyGarmentSurface(new T.MeshPhysicalMaterial({color:v.pantsColor,roughness:.95,sheen:.6}),{...v,artwork:null});const hip=new T.Mesh(new T.LatheGeometry([new T.Vector2(.23,.17),new T.Vector2(.32,.255),new T.Vector2(.345,.34),new T.Vector2(.349,.40)],64),pants);hip.scale.z=.85;hip.name='tailored-trousers';root.add(hip);for(const leg of legs){const trouser=new T.Mesh(new T.LatheGeometry([new T.Vector2(.122,-.14),new T.Vector2(.142,-.08),new T.Vector2(.137,.03),new T.Vector2(.12,.08)],48),pants.clone());trouser.scale.z=1.13;trouser.position.z=.022;trouser.name='tailored-trouser-leg';leg.add(trouser);trouser.userData.wardrobeSlot="garment";extras.push(trouser)}}
 const rows=40,segments=96,positions=[],uv=[],indices=[],top=v.kind==='skirt'?.46:.715,bottom=['top','set'].includes(v.kind)?.46-v.length*.3:.46-v.length;
 for(let j=0;j<=rows;j++){const y=top+(bottom-top)*j/rows;const torso=garmentRadius(y);const t=Math.max(0,(.46-y)/v.length),r=['top','set'].includes(v.kind)?torso: y>=.46?torso:garmentRadius(.46)+v.flare*t;for(let i=0;i<=segments;i++){const a=i/segments*Math.PI*2,fold=v.pleats?Math.cos(a*v.pleats)*.01*t:0;const neckline=v.kind==='skirt'?0:Math.pow(1-j/rows,8)*(.045*Math.max(0,Math.cos(a))+.012*Math.abs(Math.sin(a)));positions.push(Math.sin(a)*(r+fold),y-neckline,Math.cos(a)*(r+fold)*.81);uv.push(i/segments,j/rows)}}for(let j=0;j<rows;j++)for(let i=0;i<segments;i++){const a=j*(segments+1)+i,b=a+segments+1;indices.push(a,b,a+1,b,b+1,a+1)}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(positions,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(indices);g.computeVertexNormals();mesh=new T.Mesh(g,material);mesh.castShadow=mesh.receiveShadow=true;root.add(mesh);
 if(['top','set'].includes(v.kind)){
 const trim=new T.MeshStandardMaterial({color:v.accent,roughness:.85});
 const seam=new T.MeshStandardMaterial({color:new T.Color(v.color).multiplyScalar(.7),roughness:1});
 const ring=(radius,y,thickness,mat)=>{const m=new T.Mesh(new T.TorusGeometry(radius,thickness,8,80),mat);m.rotation.x=Math.PI/2;m.scale.y=.81;m.position.y=y;root.add(m);};
 const collarPoints=[];for(let i=0;i<=96;i++){const a=i/96*Math.PI*2,y=.715-.045*Math.max(0,Math.cos(a))-.012*Math.abs(Math.sin(a));collarPoints.push(new T.Vector3(Math.sin(a)*garmentRadius(.715),y,Math.cos(a)*garmentRadius(.715)*.81))}root.add(new T.Mesh(new T.TubeGeometry(new T.CatmullRomCurve3(collarPoints),96,.003,8,false),trim));ring(garmentRadius(bottom),bottom+.002,.003,seam);
 if(v.kind==='set'){
 const line=(points,r,mat)=>{const m=new T.Mesh(new T.TubeGeometry(new T.CatmullRomCurve3(points.map(([x,y])=>new T.Vector3(x,y,frontSurface(x,y)+.003))),40,r,8,false),mat);root.add(m);return m;};
 line([[0,bottom+.016],[0,.46],[0,.59],[0,.699]],.003,seam);
 const teeth=new T.MeshStandardMaterial({color:'#9a9b98',roughness:.65,metalness:.2});
 for(let i=0;i<24;i++){const y=bottom+.02+i*(.675-bottom)/24;const tooth=new T.Mesh(new T.BoxGeometry(.004,.003,.002),teeth);tooth.position.set(i%2?.003:-.003,y,frontSurface(0,y)+.005);root.add(tooth);}
 const pull=new T.Mesh(new T.TorusGeometry(.005,.0015,6,12),teeth);pull.position.set(0,.678,frontSurface(0,.678)+.007);root.add(pull);
 for(const side of [-1,1])line([[side*.12,.47],[side*.16,.49],[side*.19,.53]],.002,seam);

 }
 }
 rest=Float32Array.from(positions);tick()}
 function tick(){root.visible=!!spec&&!sleeping&&!rain;for(const extra of extras)extra.visible=root.visible;if(!mesh||!root.visible)return;const sit=T.MathUtils.clamp(-Math.min(...legs.map(x=>x.rotation.x))/1.15,0,1),p=mesh.geometry.attributes.position;for(let i=0;i<p.count;i++){const x=rest[i*3],y=rest[i*3+1],z=rest[i*3+2],t=['top','set'].includes(spec.kind)?0:Math.max(0,(.46-y)/spec.length),front=T.MathUtils.smoothstep(z,-.03,.25);p.setXYZ(i,x,y+sit*t*front*.12,z+sit*t*front*.10)}p.needsUpdate=true;mesh.geometry.computeVertexNormals();mesh.geometry.computeBoundingSphere()}
 return {set,tick,sleep(v){sleeping=v;tick()},rain(v){rain=v;tick()}};
}
